<?php

declare(strict_types=1);

namespace Bjanczak\FilamentFlexFields\Support\Playground;

/**
 * Playground-only inline PNG silhouettes (per-figure crop, transparent background).
 *
 * @internal
 */
final class ImageChoiceCardsPlaygroundSilhouettes
{
    /**
     * @return array{slim: string, average: string, athletic: string, shredded: string}
     */
    public static function dataUris(): array
    {
        return [
            "slim" => "data:image/png;base64,",
            "average" => "data:image/png;base64,",
            "athletic" => "data:image/png;base64,",
            "shredded" => "data:image/png;base64,",
        ];
    }
}
